INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('91ad84a7-0dea-5307-b266-8275dbac49da'::uuid, 'd13b307a-f8e6-5e1b-81e0-cf3f73a40f55'::uuid, 'Engineering firm — offre clé en main', 'Mission de professionnels BTP portée par B.E.T.K, basé à El Jadida. Le bureau d’études intervient sur tout type de projet de construction ou de rénovation, de la conception (études) à la réalisation (travaux). L’équipe est composée d’ingénieurs expérimentés, place ses compétences et son expertise à votre service… La mission couvre typiquement les volets réalisation / accompagnement : Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu, Expertise Engineering firm, Suivi jusqu''à livraison de la mission. B.E.T.K intervient à El Jadida, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation engineering firm, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Architecture / Ingénierie', 'https://lechantier.ma/uploads/media/1ce2867a536f.webp', '["https://lechantier.ma/uploads/media/1ce2867a536f.webp"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Engineering firm", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["El Jadida"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_catego