INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('faf2b132-877e-582b-a0e5-64f6de5dd095'::uuid, '3067db8e-e3f8-5296-810c-62dd61a05f48'::uuid, 'Professionnel BTP — offre clé en main', 'Mission de professionnels BTP portée par Haou Oussama, basé à Casablanca. 1\. 🔨 صانع الجمال من الخشب 2. 🪵 اليد اللي تحول الخشب لفن 3. ✨ نجّار بإحساس الفنان ودقّة الحرفي 4. 🪚 من الخشب نخلق الدفء والجمال 5. 🌟 نجّار يعشق التفاصيل ويهتم بالكمال 6. 🧰 كل قطعة نخشبها عندي فيها حكاية 7. 🏡 نصنع الأناقة بلمسة من الخشب La mission couvre typiquement les volets réalisation / accompagnement : نجار, أبواب خشبية, Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu. Haou Oussama intervient à Casablanca, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation professionnel btp, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Matériaux & équipements', 'https://lechantier.ma/uploads/media/703de27ae918.webp', '["https://lechantier.ma/uploads/media/703de27ae918.webp", "https://lechantier.ma/uploads/media/0dbd46ed0b00.webp", "https://lechantier.ma/uploads/media/76bdea9f0897.webp", "https://lechantier.ma/uploads/media/f2091611f367.webp"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["نجار", "أبواب خشبية", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Professionnel BTP", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
